import{_ as n,C as r,o as i,c as a,a2 as o,E as e}from"./chunks/framework.BSaF8iZ6.js";const _=JSON.parse('{"title":"Product Discounts","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/product-discounts.md","filePath":"marketing/product-discounts.md","lastUpdated":1789411447000}'),d={name:"marketing/product-discounts.md"};function c(l,t,u,g,h,p){const s=r("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=o('<h1 id="product-discounts" tabindex="-1">Product Discounts <a class="header-anchor" href="#product-discounts" aria-label="Permalink to &quot;Product Discounts&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>A product discount lowers the price of your products automatically, with no coupon. Customers see the reduced price on the storefront while the discount runs.</p><p>A product discount only lowers the price of products you created. Catalog products you sell as your own aren&#39;t included. Discounts don&#39;t need the admin&#39;s approval.</p><p>To take part in the store&#39;s own discounts, see <a href="./join-product-discounts">Joining Admin Discounts</a>.</p><h2 id="create-a-product-discount" tabindex="-1">Create a product discount <a class="header-anchor" href="#create-a-product-discount" aria-label="Permalink to &quot;Create a product discount&quot;">​</a></h2><ol><li>Go to <strong>Marketing &gt;&gt; Product Discounts</strong>.</li><li>Click <strong>Create Product Discount</strong>.</li><li>Fill in the <strong>Discount</strong>, <strong>Details</strong> and <strong>Advanced</strong> tabs, described below.</li><li>Click <strong>Save Product Discount</strong>.</li></ol><p>A tab with a mistake shows a red count, and the form opens that tab when you save.</p><p>You&#39;ll see <strong>Product discount created successfully.</strong></p><h3 id="discount" tabindex="-1">Discount <a class="header-anchor" href="#discount" aria-label="Permalink to &quot;Discount&quot;">​</a></h3>',10)),e(s,{src:"/images/product-discounts/discount.png",alt:"The Discount tab of a product discount"}),t[1]||(t[1]=o('<ol><li>Under <strong>How would you like to discount these products?</strong>, choose <strong>Percentage off the price</strong> or <strong>Fixed amount off the price</strong>.</li><li>Enter the <strong>Discount Amount</strong>. A percentage can&#39;t be more than 100, and a fixed amount can&#39;t take a price below zero.</li></ol><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3>',2)),e(s,{src:"/images/product-discounts/details.png",alt:"The Details tab of a product discount"}),t[2]||(t[2]=o('<ol><li>Under <strong>What should this discount be called?</strong>, enter a <strong>Name</strong> and, if you like, a <strong>Description</strong>.</li><li>Under <strong>When should it run?</strong>, choose the <strong>Starts From</strong> and <strong>Ends Till</strong> dates.</li></ol><h3 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h3>',2)),e(s,{src:"/images/product-discounts/advanced.png",alt:"The Advanced tab with conditions and settings"}),t[3]||(t[3]=o('<p>Under <strong>Which products should it match?</strong>, choose the products the discount covers:</p><ol><li>In <strong>Condition Type</strong>, choose <strong>All Conditions Are True</strong> or <strong>Any Condition Is True</strong>.</li><li>Click <strong>Add Condition</strong>.</li><li>Choose what to check, such as <strong>Categories</strong>, <strong>Attribute Family</strong>, <strong>Price</strong> or <strong>Color</strong>.</li><li>Choose how to compare it, and the value.</li></ol><p>With no conditions, the discount covers all your products.</p><table tabindex="0"><thead><tr><th>For</th><th>You can compare with</th></tr></thead><tbody><tr><td>Numbers, prices and dates</td><td><strong>Is equal to</strong>, <strong>Is not equal to</strong>, <strong>Equals or greater than</strong>, <strong>Equals or less than</strong>, <strong>Greater than</strong>, <strong>Less than</strong></td></tr><tr><td>Text</td><td><strong>Is equal to</strong>, <strong>Is not equal to</strong>, <strong>Contains</strong>, <strong>Does not contain</strong></td></tr><tr><td>Yes/No and single choices</td><td><strong>Is equal to</strong>, <strong>Is not equal to</strong></td></tr><tr><td>Multiple choices and categories</td><td><strong>Contains</strong>, <strong>Does not contain</strong></td></tr></tbody></table><p>In <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Channels</strong></td><td>The channels the discount runs on. All your channels are selected at first. If none is selected, it runs on all of them.</td></tr><tr><td><strong>Customer Groups</strong></td><td>The customer groups who get the discount. All groups are selected at first. If none is selected, every group gets it.</td></tr><tr><td><strong>Priority</strong></td><td>The order discounts are applied in, starting from the lowest number. This covers your own discounts and the store discounts you&#39;ve joined.</td></tr><tr><td><strong>Stop Further Rules</strong></td><td>Choose <strong>Yes</strong> so that, once this discount applies, no discount with a higher priority number applies, including store discounts you&#39;ve joined.</td></tr><tr><td><strong>Status</strong></td><td>Switches the discount on or off.</td></tr></tbody></table><p>When several discounts match a product, each one comes off the price left by the one before, until a discount with <strong>Stop Further Rules</strong> set to <strong>Yes</strong>.</p><h2 id="manage-your-discounts" tabindex="-1">Manage your discounts <a class="header-anchor" href="#manage-your-discounts" aria-label="Permalink to &quot;Manage your discounts&quot;">​</a></h2><p>The <strong>Product Discounts</strong> list shows each discount&#39;s name, whether it is active, its priority and its dates. Click the edit icon to change a discount, or the delete icon to remove it. Removing or switching off a discount returns your products to their normal price.</p><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Product Discounts</strong> to see the discounts sellers have created, with the <strong>Seller</strong>, status, priority and dates. You can filter the list by status. To delete a seller&#39;s discount, click its delete icon, or tick several and use <strong>Select Action &gt;&gt; Delete</strong>. Seller discounts aren&#39;t listed under <strong>Marketing &gt;&gt; Promotions &gt;&gt; Catalog Rules</strong>. To create a discount sellers can join, see <a href="./join-product-discounts">Joining Admin Discounts</a>.</p>',11)),e(s,{src:"/images/product-discounts/admin-product-discounts.png",alt:"Seller product discounts in the admin panel"}),t[4]||(t[4]=o('<h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>Product Discounts</strong>, with <strong>Create</strong>, <strong>Edit</strong> and <strong>Delete</strong> as needed. <strong>Join</strong>, with <strong>View</strong>, <strong>Enroll</strong> and <strong>Withdraw</strong>, covers taking part in the store&#39;s discounts.</li><li>Admins need <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Product Discounts</strong> with <strong>Delete</strong> to delete sellers&#39; discounts.</li></ul>',2))])}const f=n(d,[["render",c]]);export{_ as __pageData,f as default};
